with filtered_subscriptions as (select *, floor(monthly_fee) monthly_fee_whole from subscriptions where status = 'EXPIRED'), subscriptions_stats as (select plan, quarter(end_date) end_quarter, count(monthly_fee_whole) monthly_fee_whole_count, sum(case when status = 'EXPIRED' then monthly_fee_whole else 0 end) expired_monthly_fee_whole from filtered_subscriptions group by plan, quarter(end_date)) select plan, end_quarter, expired_monthly_fee_whole from subscriptions_stats order by end_quarter desc, plan;
